algorithm CheckPalindrome
    define mutable word as string <- "";
    read word;
    define wordLength as integer <- length(word);
    define mutable isPalindrome as integer <- 1;
    for i <- 0 to wordLength div 2 - 1 step 1 do
        if charAt(word, i) <> charAt(word, wordLength - 1 - i) then
            isPalindrome <- 0;
        endIf
    endFor
    write isPalindrome;
endAlgorithm
